'use client';

import { useEffect, useRef, type CSSProperties, type ReactNode } from 'react';
import { useReducedMotion } from './use-reduced-motion';
import './parallax-layers.css';

export interface ParallaxLayer {
  /** 0 stays put, 1 moves with the content, in between drifts slower. */
  depth: number;
  content: ReactNode;
}

export interface ParallaxLayersProps {
  /** Back to front. Decorative: hidden from assistive tech. */
  layers: ParallaxLayer[];
  /** The content that scrolls over the scene. */
  children: ReactNode;
  label: string;
  className?: string;
}

/**
 * A small scrolling viewport where background layers drift at different
 * speeds behind the content. With reduced motion the scene stays still.
 */
export function ParallaxLayers({
  layers,
  children,
  label,
  className = '',
}: ParallaxLayersProps) {
  const el = useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();

  useEffect(() => {
    const node = el.current;
    if (!node) return;
    let frame = 0;
    const update = () => {
      frame = 0;
      node.style.setProperty(
        '--mg-scroll',
        reduced ? '0' : String(node.scrollTop)
      );
    };
    const onScroll = () => {
      if (!frame) frame = requestAnimationFrame(update);
    };
    update();
    node.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      node.removeEventListener('scroll', onScroll);
      cancelAnimationFrame(frame);
    };
  }, [reduced]);

  return (
    <div
      ref={el}
      className={`mg-parallax ${className}`}
      tabIndex={0}
      role='region'
      aria-label={label}
    >
      <div className='mg-parallax__scene' aria-hidden='true'>
        {layers.map((layer, index) => (
          <div
            key={index}
            className='mg-parallax__layer'
            style={{ '--mg-depth': 1 - layer.depth } as CSSProperties}
          >
            {layer.content}
          </div>
        ))}
      </div>
      <div className='mg-parallax__content'>{children}</div>
    </div>
  );
}

.mg-parallax {
  --mg-scroll: 0;
  --mg-height: 240px;
  position: relative;
  height: var(--mg-height);
  overflow-y: auto;
  overscroll-behavior: contain;
  border-radius: 14px;
  background: #dbe5ff;
}

.mg-parallax:focus-visible {
  outline: 3px solid var(--mg-accent, #164cff);
  outline-offset: 2px;
}

/* Pinned behind the content; each layer counters part of the scroll. */
.mg-parallax__scene {
  position: sticky;
  top: 0;
  height: var(--mg-height);
  margin-bottom: calc(var(--mg-height) * -1);
  overflow: hidden;
}

.mg-parallax__layer {
  position: absolute;
  inset: 0;
  transform: translateY(calc(var(--mg-scroll) * var(--mg-depth) * -1px));
  will-change: transform;
}

.mg-parallax__layer > * {
  display: block;
  width: 100%;
  height: auto;
}

.mg-parallax__content {
  position: relative;
  padding: 150px 14px 40px;
}

@media (prefers-reduced-motion: reduce) {
  .mg-parallax__layer {
    transform: none;
  }
}

'use client';

import { useEffect, useState } from 'react';

/** True when the user has asked for reduced motion. Follows live changes. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}
